<script lang="ts">
 import {onDestroy,untrack} from 'svelte';
 import type {ImportedTitle,MetadataImportsGateway,MetadataSource} from '../application/metadata-import';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 let {gateway,actor,project='',hasValues=false,contextKey='',disabled=false,onbusy=()=>{},onimport}:{gateway:MetadataImportsGateway;actor:string;project?:string;hasValues?:boolean;contextKey?:string;disabled?:boolean;onbusy?:(busy:boolean)=>void;onimport:(item:ImportedTitle,cover?:File)=>{omittedTags:number}|void}=$props();
 const {locale}=useLocale();
 let source=$state<MetadataSource>('shikimori'),query=$state(''),items=$state<ImportedTitle[]>([]),selected=$state<ImportedTitle|null>(null),busy=$state(false),error=$state(''),searched=$state(false);let generation=0;let coverPreview=$state(''),omittedTags=$state(0);
 onDestroy(()=>{generation++;onbusy(false);if(coverPreview)URL.revokeObjectURL(coverPreview)});
 $effect(()=>{actor;project;contextKey;untrack(()=>{generation++;items=[];selected=null;if(coverPreview){URL.revokeObjectURL(coverPreview);coverPreview=''}error='';searched=false;busy=false;onbusy(false);});});
 function reset(){generation++;items=[];searched=false;error='';busy=false;}
 async function search(){const run=++generation,account=actor;busy=true;onbusy(true);error='';items=[];try{const result=await gateway.search(account,project,source,query);if(run===generation){items=result;searched=true}}catch{if(run===generation)error=text($locale,'Дереккөзге қосылу мүмкін болмады немесе сұрау шегіне жетті. Сәл кейін қайталаңыз.','Источник недоступен или достигнут лимит запросов. Повторите чуть позже.')}finally{if(run===generation){busy=false;onbusy(false)}}}
 async function choose(item:ImportedTitle){if(hasValues&&!window.confirm(text($locale,'Қолжетімді деректерді осы дереккөзден толтыру керек пе? Сәйкес өрістердегі қолмен енгізілген мәндер ауысады. Бос деректер бұрынғы мәндерді сақтайды.','Заполнить доступные данные из этого источника? Ручные значения в соответствующих полях будут заменены. Отсутствующие данные сохранят прежние значения.')))return;const run=++generation,account=actor;busy=true;onbusy(true);error='';try{const result=await gateway.select(account,project,item.source,item.id);if(run!==generation)return;let cover:File|undefined;if(result.coverUrl&&project){try{const artwork=await gateway.cover(account,project,result.source,result.id);if(artwork.content instanceof File)cover=artwork.content;else throw Error('Invalid artwork')}catch{if(run===generation)error=text($locale,'Мәтін толтырылды, мұқаба жүктелмеді. Суретті қолмен қосуға болады.','Текст заполнен, обложка не загрузилась. Изображение можно добавить вручную.')}}if(run!==generation)return;selected=result;if(coverPreview)URL.revokeObjectURL(coverPreview);coverPreview=cover?URL.createObjectURL(cover):'';omittedTags=onimport(result,cover)?.omittedTags||0}catch{if(run===generation)error=text($locale,'Тайтл деректері жүктелмеді. Сәл кейін қайта таңдаңыз.','Не удалось загрузить данные тайтла. Повторите выбор чуть позже.')}finally{if(run===generation){busy=false;onbusy(false)}}}
</script>
<section class="import" aria-label={text($locale,'Дереккөзден толтыру','Заполнить из источника')}>
 <h3>{text($locale,'Дереккөзден толтыру','Заполнить из источника')}</h3>
 <p class="muted">{text($locale,'Тайтлды іздеп таңдаңыз. Деректер сақталмас бұрын осы формада өңделеді.','Найдите и выберите тайтл. Данные можно проверить и изменить в этой форме перед сохранением.')}</p>
 <div class="search"><label>{text($locale,'Дереккөз','Источник')}<select bind:value={source} onchange={reset} disabled={busy||disabled}><option value="shikimori">Shikimori</option><option value="anilist">AniList</option></select></label>
 <label>{text($locale,'Сыртқы тайтлды іздеу','Поиск внешнего тайтла')}<input type="search" bind:value={query} minlength="2" maxlength="160" onkeydown={e=>{if(e.key==='Enter'){e.preventDefault();if(query.trim().length>=2&&!busy)void search()}}}/></label>
 <button type="button" class="button subtle" disabled={busy||disabled||query.trim().length<2||!actor} onclick={search}>{text($locale,'Іздеу','Найти')}</button></div>
 {#if busy}<p role="status">{text($locale,'Деректер жүктелуде…','Загрузка данных…')}</p>{/if}
 {#if error}<p role="alert">{error}</p><button type="button" class="button subtle" disabled={busy||disabled} onclick={search}>{text($locale,'Қайталау','Повторить поиск')}</button>{/if}
 {#if searched&&!items.length&&!busy&&!error}<p role="status">{text($locale,'Тайтл табылмады. Басқа атаумен іздеңіз.','Тайтлы не найдены. Попробуйте другое название.')}</p>{/if}
 <ul>{#each items as item}<li><button type="button" class:with-cover={!!item.coverUrl} disabled={busy||disabled} onclick={()=>choose(item)}>{#if item.coverUrl}<img src={'/api/v1/metadata-imports/thumbnail?'+new URLSearchParams({source:item.source,id:item.id,project}).toString()} loading="lazy" alt=""/>{/if}<strong>{item.name}</strong><span>{item.originalName||item.aliases[0]||''}</span><span>{item.source} #{item.id} · {item.kind||'—'} · {item.year||'—'}</span></button></li>{/each}</ul>
 {#if coverPreview}<img class="cover-preview" src={coverPreview} alt={text($locale,'Ұсынылатын мұқаба','Предлагаемая обложка')}/>{/if}
 {#if selected}<div class="provenance" role="status"><a href={selected.url} target="_blank" rel="noopener noreferrer">{selected.source} #{selected.id}</a><p>{text($locale,'Қолжетімді өрістер толтырылды. Атаулар автоматты аударылмайды.','Доступные поля заполнены. Названия автоматически не переводятся.')}</p>{#if selected.coverUrl}<p>{project&&coverPreview?text($locale,'Ұсынылған мұқаба модерацияға жіберілетін формаға қосылады.','Предлагаемая обложка добавляется в форму заявки на модерацию.'):text($locale,'Дереккөздің мұқабасы сақталмады. Мұқаба жоба деректерін өзгерту өтінімі арқылы ауыстырылады.','Обложка источника не сохранена. Обложка меняется через заявку на данные проекта.')}</p>{/if}
 {#if omittedTags}<p>{text($locale,'Барлық тег қосылмады: формадағы шекке жетті. Қосылмаған тег саны: ','Не все теги добавлены: достигнут лимит формы. Количество не добавленных тегов: ')}{omittedTags}. {text($locale,'Дереккөздегі тегтерді тексеріңіз.','Проверьте теги по ссылке источника.')}</p>{/if}
 {#if selected.candidates.length}<p>{text($locale,'Сәйкестендіру үшін сақталған тегтер:','Теги сохранены для согласования:')}</p><ul>{#each selected.candidates as candidate}<li>{candidate.name} · {candidate.status==='ambiguous'?text($locale,'Бірнеше сәйкестік','Несколько совпадений'):text($locale,'Сәйкестік жоқ','Соответствие не найдено')}</li>{/each}</ul>{/if}</div>{/if}
</section>
<style>.cover-preview{width:100px;aspect-ratio:2/3;object-fit:cover;border-radius:6px}.import{border:1px solid var(--line);border-radius:8px;padding:16px;margin-block:16px;min-width:0}h3{margin:0}.search{display:grid;gap:12px}label{display:grid;gap:6px;min-width:0}input,select{min-width:0;max-width:100%}ul{padding:0;list-style:none}li{margin-block:8px;overflow-wrap:anywhere}li button{display:grid;text-align:left;width:100%;min-height:44px;padding:10px;gap:4px;border:1px solid var(--line);background:var(--panel);color:var(--text);border-radius:6px}li button img{width:52px;height:72px;object-fit:cover;border-radius:4px;grid-column:1;grid-row:1/4}.with-cover{grid-template-columns:52px minmax(0,1fr)}.with-cover strong,.with-cover span{grid-column:2}li button:hover{border-color:var(--accent)}li span{font-size:13px}.provenance{overflow-wrap:anywhere}.provenance p{margin-block:8px}.muted{font-size:14px;line-height:1.5}@media(min-width:700px){.search{grid-template-columns:140px minmax(0,1fr) auto;align-items:end}}</style>
